#include <iostream>
using namespace std;

int main() {
    long long x;
    cin >> x;

    x %= 360;
    int answer = 0;
    long long best = 361;

    for (int turns = 0; turns < 4; ++turns) {
        long long angle = (-x + 90LL * turns) % 360;
        if (angle < 0) angle += 360;
        long long deviation = min(angle, 360 - angle);

        if (deviation < best) {
            best = deviation;
            answer = turns;
        }
    }

    cout << answer;
    return 0;
}

#include <iostream>
#include <cstdlib>
using namespace std;

int main() {
    long long x;
    cin >> x;
    x %= 360;

    int answer = 0;
    long long best = 361;

    for (int turns = 0; turns < 4; ++turns) {
        long long angle = (90LL * turns - x) % 360;
        if (angle < 0) angle += 360;
        long long deviation = min(angle, 360 - angle);

        if (deviation < best) {
            best = deviation;
            answer = turns;
        }
    }

    cout << answer << '\n';
    return 0;
}

