#include <iostream>
#include <cstdlib>
using namespace std;

int main() {
    long long x;
    cin >> x;

    long long r = ((x % 360) + 360) % 360;
    int answer = 0;
    long long best = 361;

    for (int turns = 0; turns < 4; ++turns) {
        long long angle = ((-r + 90LL * turns) % 360 + 360) % 360;
        long long deviation = min(angle, 360 - angle);

        if (deviation < best) {
            best = deviation;
            answer = turns;
        }
    }

    cout << answer;
    return 0;
}
